164	impl Store {
165	    /// 从数据目录加载或初始化存储，并完成崩溃恢复。
166	    pub fn open(data_dir: impl AsRef<Path>) -> Result<Self, String> {
167	        let data_dir = data_dir.as_ref().to_path_buf();
168	        fs::create_dir_all(&data_dir).map_err(|e| format!("create data dir: {e}"))?;
169	
170	        let mut current: BTreeMap<String, Vec<Record>> = BTreeMap::new();
171	        let mut versions: Vec<VersionSnap> = Vec::new();
172	
173	        // 1. 恢复最近一次快照（若存在）。
174	        let snap_path = data_dir.join("snapshot.json");
175	        if snap_path.exists() {
176	            let bytes = fs::read(&snap_path).map_err(|e| format!("read snapshot: {e}"))?;
177	            let state: PersistedState =
178	                serde_json::from_slice(&bytes).map_err(|e| format!("parse snapshot: {e}"))?;
179	            for c in state.collections {
180	                current.insert(c.name, c.records);
181	            }
182	            for v in state.versions {
183	                versions.push(VersionSnap {
184	                    id: v.id,
185	                    saved_at: v.saved_at,
186	                    data: v
187	                        .collections
188	                        .into_iter()
189	                        .map(|c| (c.name, c.records))
190	                        .collect(),
191	                });
192	            }
193	        }
194	        let next_id = versions.last().map(|v| v.id + 1).unwrap_or(1);
195	
196	        // 2. 重放快照之后的 WAL，并修复崩溃残留的残缺行。
197	        let wal_path = data_dir.join("wal.log");
198	        let mut valid_bytes = 0usize;
199	        if wal_path.exists() {
200	            let content = fs::read_to_string(&wal_path).map_err(|e| format!("read wal: {e}"))?;
201	            let mut rest = content.as_str();
202	            loop {
203	                if rest.is_empty() {
204	                    break;
205	                }
206	                let Some(nl) = rest.find('\n') else {
207	                    // 最后一行没有换行结尾：本服务的提交总是以换行结尾，故必为残缺行。
208	                    break;
209	                };
210	                let line = &rest[..nl];
211	                match serde_json::from_str::<CommitEvent>(line) {
212	                    Ok(event) => {
213	                        apply_commit(&mut current, event.collection, event.records);
214	                        valid_bytes += nl + 1;
215	                        rest = &rest[nl + 1..];
216	                    }
217	                    Err(_) => break,
218	                }
219	            }
220	            if valid_bytes < content.len() {
221	                let f = fs::OpenOptions::new()
222	                    .write(true)
223	                    .open(&wal_path)
224	                    .map_err(|e| format!("repair wal: {e}"))?;
225	                f.set_len(valid_bytes as u64)
226	                    .map_err(|e| format!("repair wal: {e}"))?;
227	                f.sync_all().ok();
228	            }
229	        }
230	
231	        // 3. 打开 WAL 供后续追加。
232	        let wal = fs::OpenOptions::new()
233	            .create(true)
234	            .append(true)
235	            .open(&wal_path)
236	            .map_err(|e| format!("open wal: {e}"))?;
237	
238	        Ok(Store {
239	            inner: Mutex::new(Inner {
240	                current,
241	                versions,
242	                next_id,
243	                wal,
244	            }),
245	            data_dir,
246	        })
247	    }
248	
249	    /// 批量写入：整批校验通过后原子提交，任一条不合法则整批拒绝、已有数据不变。
250	    ///
251	    /// `replace=false`（默认）时，同主键不同内容整批拒绝；`replace=true` 时允许用
252	    /// 新内容覆盖同主键的已有记录。两种模式下同批主键重复、非法记录等校验完全一致，
253	    /// 且任一记录不合法时整批不生效（包括不会发生任何替换）。
254	    pub fn write_batch(
255	        &self,
256	        collection: &str,
257	        batch: &[Value],
258	        replace: bool,
259	    ) -> Result<WriteOutcome, BatchError> {
260	        if collection.is_empty() {
261	            return Err(BatchError::Rejected(Rejection {
262	                index: 0,
263	                id: None,
264	                reason: "collection name must not be empty".to_string(),
265	            }));
266	        }
267	
268	        let mut st = self.inner.lock().unwrap();
269	
270	        // 阶段 1：逐条校验；任何失败都直接返回，状态未做任何修改。
271	        let mut seen: HashMap<&str, usize> = HashMap::with_capacity(batch.len());
272	        let mut prepared: Vec<Record> = Vec::with_capacity(batch.len());
273	        for (i, raw) in batch.iter().enumerate() {
274	            let rec = match raw {
275	                Value::Object(map) => map,
276	                _ => {
277	                    return Err(BatchError::Rejected(Rejection {
278	                        index: i,
279	                        id: None,
280	                        reason: "record must be a JSON object".to_string(),
281	                    }));
282	                }
283	            };
284	            let id = match rec.get("id") {
285	                None => {
286	                    return Err(BatchError::Rejected(Rejection {
287	                        index: i,
288	                        id: None,
289	                        reason: "missing primary key field \"id\"".to_string(),
290	                    }));
291	                }
292	                Some(Value::String(s)) if !s.is_empty() => s.as_str(),
293	                Some(Value::String(_)) => {
294	                    return Err(BatchError::Rejected(Rejection {
295	                        index: i,
296	                        id: None,
297	                        reason: "primary key \"id\" must be a non-empty string".to_string(),
298	                    }));
299	                }
300	                Some(_) => {
301	                    return Err(BatchError::Rejected(Rejection {
302	                        index: i,
303	                        id: None,
304	                        reason: "primary key \"id\" must be a string".to_string(),
305	                    }));
306	                }
307	            };
308	            if let Some(&first) = seen.get(id) {
309	                return Err(BatchError::Rejected(Rejection {
310	                    index: i,
311	                    id: Some(id.to_string()),
312	                    reason: format!(
313	                        "duplicate id \"{id}\" in the same batch (first at index {first})"
314	                    ),
315	                }));
316	            }
317	            for (field, value) in rec.iter() {
318	                if let Err(msg) = validate_value(value) {
319	                    return Err(BatchError::Rejected(Rejection {
320	                        index: i,
321	                        id: Some(id.to_string()),
322	                        reason: format!("field \"{field}\": {msg}"),
323	                    }));
324	                }
325	            }
326	            seen.insert(id, i);
327	            prepared.push(rec.clone());
328	        }
329	
330	        // 阶段 2：与集合中已有记录冲突检查——replace=false 时同主键不同内容拒绝整批；
331	        // replace=true 时同主键不同内容将在提交阶段覆盖，此处跳过。
332	        if !replace && let Some(existing) = st.current.get(collection) {
333	            for (i, rec) in prepared.iter().enumerate() {
334	                let id = rec["id"].as_str().unwrap();
335	                if let Some(old) = existing.iter().find(|r| r["id"] == id)
336	                    && old != rec
337	                {
338	                    return Err(BatchError::Rejected(Rejection {
339	                        index: i,
340	                        id: Some(id.to_string()),
341	                        reason: format!(
342	                            "collection \"{collection}\" already contains a different record with id \"{id}\""
343	                        ),
344	                    }));
345	                }
346	            }
347	        }
348	
349	        // 阶段 3：先持久化（追加 WAL 并 fsync），成功后才更新内存并确认成功。
350	        let event = CommitEvent {
351	            collection: collection.to_string(),
352	            records: prepared.clone(),
353	            replace,
354	        };
355	        append_wal(&mut st.wal, &event).map_err(BatchError::Persist)?;
356	
357	        let existing = st.current.entry(collection.to_string()).or_default();
358	        let mut inserted = 0usize;
359	        let mut replaced = 0usize;
360	        for rec in prepared {
361	            let id = rec["id"].as_str().unwrap();
362	            match existing.iter().position(|r| r["id"] == id) {
363	                Some(pos) => {
364	                    // 内容相同为幂等写入；内容不同（只可能发生在 replace=true）计为替换。
365	                    if existing[pos] != rec {
366	                        replaced += 1;
367	                    }
368	                    existing[pos] = rec;
369	                }
370	                None => {
371	                    existing.push(rec);
372	                    inserted += 1;
373	                }
374	            }
375	        }
376	
377	        Ok(WriteOutcome {
378	            collection: collection.to_string(),
379	            accepted: batch.len(),
380	            inserted,
381	            replaced,
382	        })
383	    }
