424	    /// 比较同一集合在两个已保存版本之间的差异。
425	    ///
426	    /// 只读取快照，不生成新版本、不改写任何数据。记录内容比较与写入冲突检测一致：
427	    /// 字段顺序不影响判定，字段名与字段值相同即视为同一条记录。
428	    pub fn diff_versions(
429	        &self,
430	        from: u64,
431	        to: u64,
432	        collection: &str,
433	    ) -> Result<DiffOutcome, DiffError> {
434	        let st = self.inner.lock().unwrap();
435	        let from_v = st
436	            .versions
437	            .iter()
438	            .find(|v| v.id == from)
439	            .ok_or(DiffError::FromVersionNotFound)?;
440	        let to_v = st
441	            .versions
442	            .iter()
443	            .find(|v| v.id == to)
444	            .ok_or(DiffError::ToVersionNotFound)?;
445	        if from > to {
446	            return Err(DiffError::OutOfOrder);
447	        }
448	        let from_recs = from_v
449	            .data
450	            .get(collection)
451	            .ok_or(DiffError::CollectionNotFoundInFrom)?;
452	        let to_recs = to_v
453	            .data
454	            .get(collection)
455	            .ok_or(DiffError::CollectionNotFoundInTo)?;
456	
457	        // BTreeMap 迭代顺序即主键 id 的字节序升序。
458	        let from_map: BTreeMap<&str, &Record> = from_recs
459	            .iter()
460	            .map(|r| (r["id"].as_str().expect("validated record"), r))
461	            .collect();
462	        let to_map: BTreeMap<&str, &Record> = to_recs
463	            .iter()
464	            .map(|r| (r["id"].as_str().expect("validated record"), r))
465	            .collect();
466	
467	        let mut added = Vec::new();
468	        let mut dropped = Vec::new();
469	        let mut changed = Vec::new();
470	        for (id, before) in &from_map {
471	            match to_map.get(id) {
472	                None => added.push((*before).clone()),
473	                Some(after) if **after != **before => changed.push(ChangedRecord {
474	                    before: (*before).clone(),
475	                    after: (*after).clone(),
476	                }),
477	                Some(_) => {}
478	            }
479	        }
480	        for (id, after) in &to_map {
481	            if !from_map.contains_key(id) {
482	                dropped.push((*after).clone());
483	            }
484	        }
485	
486	        Ok(DiffOutcome {
487	            from,
488	            to,
489	            collection: collection.to_string(),
490	            added,
491	            dropped,
492	            changed,
493	        })
494	    }
