524	/// WAL 重放/应用：按主键 upsert；整批来自同一个 commit 事件。
525	fn apply_commit(
526	    current: &mut BTreeMap<String, Vec<Record>>,
527	    collection: String,
528	    records: Vec<Record>,
529	) {
530	    let entry = current.entry(collection).or_default();
531	    for rec in records {
532	        let id = rec["id"].as_str().expect("validated commit");
533	        match entry.iter().position(|r| r["id"] == id) {
534	            Some(pos) => entry[pos] = rec,
535	            None => entry.push(rec),
536	        }
537	    }
538	}
