783	    fn diff_versions_reports_added_dropped_changed_sorted() {
784	        let dir = temp_dir();
785	        let store = Store::open(&dir).unwrap();
786	
787	        // v1：三条记录；b 的字段顺序与 v2 不同但内容相同，不应算作 changed。
788	        store
789	            .write_batch(
790	                "users",
791	                &[
792	                    json!({"id": "b", "x": 1, "y": 2}),
793	                    json!({"id": "gone", "v": 1}),
794	                    json!({"id": "mod", "v": 1}),
795	                ],
796	                false,
797	            )
798	            .unwrap();
799	        let v1 = store.save_version().unwrap();
800	
801	        // v2：gone 被删除、mod 内容变化、new 新写入（写入接口不产生删除/修改，
802	        // 直接注入快照模拟这两个方向）。
803	        store
804	            .write_batch("users", &[json!({"id": "new", "v": 9})], false)
805	            .unwrap();
806	        let v2 = store.save_version().unwrap();
807	        {
808	            let mut st = store.inner.lock().unwrap();
809	            let data = st.versions[1].data.get_mut("users").unwrap();
810	            data.retain(|r| r["id"] != "gone");
811	            let m = data.iter_mut().find(|r| r["id"] == "mod").unwrap();
812	            m.insert("v".to_string(), json!(2));
813	            let b = data.iter_mut().find(|r| r["id"] == "b").unwrap();
814	            *b = json!({"y": 2, "id": "b", "x": 1})
815	                .as_object()
816	                .unwrap()
817	                .clone();
818	        }
819	
820	        let d = store.diff_versions(v1.id, v2.id, "users").unwrap();
821	        let added_ids: Vec<_> = d.added.iter().map(|r| r["id"].as_str().unwrap()).collect();
822	        assert_eq!(added_ids, vec!["gone"]);
823	        assert_eq!(
824	            Value::Object(d.added[0].clone()),
825	            json!({"id": "gone", "v": 1})
826	        );
827	        let dropped_ids: Vec<_> = d
828	            .dropped
829	            .iter()
830	            .map(|r| r["id"].as_str().unwrap())
831	            .collect();
832	        assert_eq!(dropped_ids, vec!["new"]);
833	        assert_eq!(d.changed.len(), 1);
834	        assert_eq!(
835	            Value::Object(d.changed[0].before.clone()),
836	            json!({"id": "mod", "v": 1})
837	        );
838	        assert_eq!(
839	            Value::Object(d.changed[0].after.clone()),
840	            json!({"id": "mod", "v": 2})
841	        );
842	
843	        // 起始版本晚于目标版本 → OutOfOrder。
844	        assert_eq!(
845	            store.diff_versions(v2.id, v1.id, "users").unwrap_err(),
846	            DiffError::OutOfOrder
847	        );
848	
849	        // 起始与目标相同 → 三个列表都为空。
850	        let d = store.diff_versions(v1.id, v1.id, "users").unwrap();
851	        assert!(d.added.is_empty() && d.dropped.is_empty() && d.changed.is_empty());
852	
853	        // 版本或集合不存在。
854	        assert_eq!(
855	            store.diff_versions(999, v1.id, "users").unwrap_err(),
856	            DiffError::FromVersionNotFound
857	        );
858	        assert_eq!(
859	            store.diff_versions(v1.id, 999, "users").unwrap_err(),
860	            DiffError::ToVersionNotFound
861	        );
862	        assert_eq!(
863	            store.diff_versions(v1.id, v2.id, "missing").unwrap_err(),
864	            DiffError::CollectionNotFoundInFrom
865	        );
866	
867	        // 差异查询不生成新版本。
868	        assert_eq!(store.list_versions().len(), 2);
869	
870	        fs::remove_dir_all(&dir).ok();
871	    }
