/// WAL 中的事件：已确认提交的一批写入，或一批删除。
///
/// 旧版本 WAL 中的写入事件只有 `collection`/`records`/`replace` 三个字段，因此给写入变体
/// 标记 `#[serde(untagged)]` 之外的区分字段不可行——这里改用显式内部标签 `"op"`：
/// 旧行没有该字段时靠 `#[serde(other)]` 风格的别名兜底。两种事件在重放时分别是
/// 按主键 upsert 与按主键删除；`replace` 只影响提交时的冲突校验，不影响重放动作本身。
#[derive(Serialize, Deserialize)]
#[serde(tag = "op")]
enum WalEvent {
    /// 一批写入（upsert）。旧版本 WAL 行没有 `"op"` 字段，用 `alias` 兼容。
    #[serde(alias = "")]
    Commit {
        collection: String,
        records: Vec<Record>,
        #[serde(default)]
        replace: bool,
    },
    /// 一批删除。
    Delete {
        collection: String,
        delete: Vec<String>,
    },
}

