            .unwrap_err();
        // 记录已删除，不存在冲突，因此这里应成功而非拒绝——修正预期：
        match err {
            BatchError::Rejected(r) => panic!("unexpected rejection: {}", r.reason),
            BatchError::Persist(e) => panic!("{e}"),
        }
    }
