    #[test]
    fn rewrite_after_delete_is_insert_and_replace_rules_still_apply() {
        let dir = temp_dir();
        let store = Store::open(&dir).unwrap();
        store
            .write_batch("users", &[json!({"id": "u1", "v": 1})], false)
            .unwrap();
