1	//! 持久化存储：集合、当前数据状态与不可变版本快照。
2	//!
3	//! 持久化采用“快照文件 + 追加式 WAL”：
4	//! - `snapshot.json` 以“临时文件 + 原子重命名”落盘，包含全部已保存版本及其快照数据、
5	//!   以及保存时刻各集合的当前数据；
6	//! - `wal.log` 逐行追加已确认提交的批量写入或删除（每行一个 JSON，以换行结尾）；
7	//! - 启动时先恢复快照，再顺序重放 WAL；末尾若存在崩溃残留的残缺行则截断，
8	//!   因此未完成（未 fsync）的写入在重启后不会产生任何记录。
9	//!
10	//! 所有提交与保存都在同一把 `Mutex` 下完成，保证线性一致：快照要么包含
11	//! 整批已提交写入，要么完全不包含，不会出现半批数据。
12	
13	use serde::{Deserialize, Serialize};
14	use serde_json::{Map, Value};
15	use std::collections::{BTreeMap, HashMap};
16	use std::fs;
17	use std::io::Write;
18	use std::path::{Path, PathBuf};
19	use std::sync::Mutex;
20	use std::time::{SystemTime, UNIX_EPOCH};
21	
22	/// 一条记录即保留字段顺序的 JSON 对象，主键为其中的 `id` 字段。
23	pub type Record = Map<String, Value>;
24	
25	/// 一次写入被业务规则拒绝：定位到批次内的记录位置、主键（若可识别）与原因。
26	#[derive(Debug, Clone, Serialize)]
27	pub struct Rejection {
28	    pub index: usize,
29	    pub id: Option<String>,
30	    pub reason: String,
31	}
32	
33	/// 写入失败：整批被拒绝（400）或持久化失败（500）。
34	#[derive(Debug)]
35	pub enum BatchError {
36	    Rejected(Rejection),
37	    Persist(String),
38	}
39	
40	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
41	pub enum LookupError {
42	    VersionNotFound,
43	    CollectionNotFound,
44	}
45	
46	/// 版本差异查询失败：版本/集合不存在（404）或起始版本晚于目标版本（400）。
47	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
48	pub enum DiffError {
49	    FromVersionNotFound,
50	    ToVersionNotFound,
51	    CollectionNotFoundInFrom,
52	    CollectionNotFoundInTo,
53	    /// 起始版本晚于目标版本（版本号随保存动作递增）。
54	    OutOfOrder,
55	}
56	
57	/// 两个版本中都存在但内容不同的一条记录：修改前与修改后的完整记录。
58	#[derive(Debug, Clone, Serialize)]
59	pub struct ChangedRecord {
60	    pub before: Record,
61	    pub after: Record,
62	}
63	
64	/// 同一集合在两个已保存版本之间的差异；三个列表均按主键 id 字节序升序。
65	#[derive(Debug, Clone, Serialize)]
66	pub struct DiffOutcome {
67	    pub from: u64,
68	    pub to: u64,
69	    pub collection: String,
70	    /// 仅存在于起始版本的记录（在目标版本中被删除）。
71	    pub added: Vec<Record>,
72	    /// 仅存在于目标版本的记录（新写入）。
73	    pub dropped: Vec<Record>,
74	    /// 两个版本中都存在但内容不同的记录。
75	    pub changed: Vec<ChangedRecord>,
76	}
77	
78	#[derive(Debug, Clone, Serialize)]
79	pub struct WriteOutcome {
80	    pub collection: String,
81	    /// 批次中被接受的记录数（等于整批大小）。
82	    pub accepted: usize,
83	    /// 实际新增的记录数（与已有记录完全相同的写入幂等，不计入）。
84	    pub inserted: usize,
85	    /// `replace=true` 时被新内容覆盖的已有记录数（内容相同的幂等写入不计入）。
86	    pub replaced: usize,
87	}
88	
89	#[derive(Debug, Clone, Serialize)]
90	pub struct DeleteOutcome {
91	    pub collection: String,
92	    /// 批次中被接受的主键数（等于整批大小）。
93	    pub accepted: usize,
94	    /// 实际被删除的记录数。
95	    pub deleted: usize,
96	    /// 给定主键中集合里不存在（幂等跳过，不报错）的条数。
97	    pub missing: usize,
98	}
99	
100	#[derive(Debug, Clone, Serialize)]
101	pub struct VersionSummary {
102	    pub id: u64,
103	    /// 保存时间（Unix 纪元毫秒）。
104	    pub saved_at: u64,
105	}
106	
107	#[derive(Debug, Clone, Serialize)]
108	pub struct VersionDetail {
109	    pub id: u64,
110	    pub saved_at: u64,
111	    /// 该版本快照中包含的集合名。
112	    pub collections: Vec<String>,
113	}
114	
115	/// 一个已保存版本的完整只读快照。
116	struct VersionSnap {
117	    id: u64,
118	    saved_at: u64,
119	    data: HashMap<String, Vec<Record>>,
120	}
121	
122	/// WAL 中的事件：已确认提交的一批写入，或一批删除。
123	///
124	/// 采用 untagged 表示，按字段形状区分：写入事件带 `records`（旧版本 WAL 行也是同一形状，
125	/// 可直接重放），删除事件带字符串数组 `delete`。两种事件在重放时分别按主键 upsert 与
126	/// 按主键删除；`replace` 只影响提交时的冲突校验，不影响重放动作本身。
127	#[derive(Serialize, Deserialize)]
128	#[serde(untagged)]
129	enum WalEvent {
130	    /// 一批写入（upsert）。
131	    Commit {
132	        collection: String,
133	        records: Vec<Record>,
134	        #[serde(default)]
135	        replace: bool,
136	    },
137	    /// 一批删除。
138	    Delete {
139	        collection: String,
140	        delete: Vec<String>,
141	    },
142	}
143	
144	#[derive(Serialize, Deserialize)]
145	struct PersistedCollection {
146	    name: String,
147	    records: Vec<Record>,
148	}
149	
150	#[derive(Serialize, Deserialize)]
151	struct PersistedVersion {
152	    id: u64,
153	    saved_at: u64,
154	    collections: Vec<PersistedCollection>,
155	}
156	
157	/// `snapshot.json` 的完整内容。
158	#[derive(Serialize, Deserialize)]
159	struct PersistedState {
160	    versions: Vec<PersistedVersion>,
161	    collections: Vec<PersistedCollection>,
162	}
163	
164	struct Inner {
165	    /// 各集合的当前数据；Vec 保存提交顺序。
166	    current: BTreeMap<String, Vec<Record>>,
167	    versions: Vec<VersionSnap>,
168	    next_id: u64,
169	    wal: fs::File,
170	}
171	
172	/// 整个服务的状态。
173	pub struct Store {
174	    inner: Mutex<Inner>,
175	    data_dir: PathBuf,
176	}
177	
178	fn now_ms() -> u64 {
179	    SystemTime::now()
180	        .duration_since(UNIX_EPOCH)
181	        .map(|d| d.as_millis() as u64)
182	        .unwrap_or(0)
183	}
184	
185	impl Store {
186	    /// 从数据目录加载或初始化存储，并完成崩溃恢复。
187	    pub fn open(data_dir: impl AsRef<Path>) -> Result<Self, String> {
188	        let data_dir = data_dir.as_ref().to_path_buf();
189	        fs::create_dir_all(&data_dir).map_err(|e| format!("create data dir: {e}"))?;
190	
191	        let mut current: BTreeMap<String, Vec<Record>> = BTreeMap::new();
192	        let mut versions: Vec<VersionSnap> = Vec::new();
193	
194	        // 1. 恢复最近一次快照（若存在）。
195	        let snap_path = data_dir.join("snapshot.json");
196	        if snap_path.exists() {
197	            let bytes = fs::read(&snap_path).map_err(|e| format!("read snapshot: {e}"))?;
198	            let state: PersistedState =
199	                serde_json::from_slice(&bytes).map_err(|e| format!("parse snapshot: {e}"))?;
200	            for c in state.collections {
201	                current.insert(c.name, c.records);
202	            }
203	            for v in state.versions {
204	                versions.push(VersionSnap {
205	                    id: v.id,
206	                    saved_at: v.saved_at,
207	                    data: v
208	                        .collections
209	                        .into_iter()
210	                        .map(|c| (c.name, c.records))
211	                        .collect(),
212	                });
213	            }
214	        }
215	        let next_id = versions.last().map(|v| v.id + 1).unwrap_or(1);
216	
217	        // 2. 重放快照之后的 WAL，并修复崩溃残留的残缺行。
218	        let wal_path = data_dir.join("wal.log");
219	        let mut valid_bytes = 0usize;
220	        if wal_path.exists() {
221	            let content = fs::read_to_string(&wal_path).map_err(|e| format!("read wal: {e}"))?;
222	            let mut rest = content.as_str();
223	            loop {
224	                if rest.is_empty() {
225	                    break;
226	                }
227	                let Some(nl) = rest.find('\n') else {
228	                    // 最后一行没有换行结尾：本服务的提交总是以换行结尾，故必为残缺行。
229	                    break;
230	                };
231	                let line = &rest[..nl];
232	                match serde_json::from_str::<WalEvent>(line) {
233	                    Ok(WalEvent::Commit {
234	                        collection,
235	                        records,
236	                        replace: _,
237	                    }) => {
238	                        apply_commit(&mut current, collection, records);
239	                        valid_bytes += nl + 1;
240	                        rest = &rest[nl + 1..];
241	                    }
242	                    Ok(WalEvent::Delete { collection, delete }) => {
243	                        apply_delete(&mut current, &collection, &delete);
244	                        valid_bytes += nl + 1;
245	                        rest = &rest[nl + 1..];
246	                    }
247	                    Err(_) => break,
248	                }
249	            }
250	            if valid_bytes < content.len() {
251	                let f = fs::OpenOptions::new()
252	                    .write(true)
253	                    .open(&wal_path)
254	                    .map_err(|e| format!("repair wal: {e}"))?;
255	                f.set_len(valid_bytes as u64)
256	                    .map_err(|e| format!("repair wal: {e}"))?;
257	                f.sync_all().ok();
258	            }
259	        }
260	
261	        // 3. 打开 WAL 供后续追加。
262	        let wal = fs::OpenOptions::new()
263	            .create(true)

