72	    }
73	    req.push_str("\r\n");
74	    if let Some(b) = body {
75	        req.push_str(b);
76	    }
77	    stream.write_all(req.as_bytes()).unwrap();
78	    let mut raw = String::new();
79	    stream.read_to_string(&mut raw).unwrap();
80	    let split = raw.find("\r\n\r\n").unwrap();
81	    let head = &raw[..split];
82	    let text = &raw[split + 4..];
83	    let status: u16 = head
84	        .lines()
85	        .next()
86	        .unwrap()
87	        .split_whitespace()
88	        .nth(1)
89	        .unwrap()
90	        .parse()
91	        .unwrap();
92	    RawResponse {
93	        status,
94	        body: serde_json::from_str(text.trim()).unwrap_or(Value::Null),
95	    }
